import{S}from"./university-sources-DkP7OoqL.js";const r=new Map;function c(){try{if(typeof localStorage<"u"&&localStorage)return localStorage}catch{}return{getItem:e=>r.has(e)?r.get(e):null,setItem:(e,t)=>{r.set(e,String(t))},removeItem:e=>{r.delete(e)}}}function o(e=new Date){return e.getFullYear()+"-"+String(e.getMonth()+1).padStart(2,"0")+"-"+String(e.getDate()).padStart(2,"0")}const q=[{id:"tc-rhythm-strong",tags:["จังหวะ","rhythm","beat","timing"],tier:0,source:"rhythm-wiki",diagram:{type:"rhythm-grid",beats:[1,.4,.6,.4]},concept:{th:"จังหวะแรกของห้องคือจังหวะ “หนัก”",en:"The first beat of the bar is the strong one",zh:"每小节的第一拍是重拍"},why:{th:"โน้ตทุกตัวดังเท่ากันทำให้จังหวะพัง — นับ 1-2-3-4 แล้วกดหนักที่ 1 มือจะจำจังหวะเอง",en:"If every note is equally loud the pulse breaks — count 1-2-3-4 and lean on beat 1; your hand starts keeping time by itself.",zh:"每个音一样响会让节奏散掉——数1-2-3-4，第1拍加重，手会自己稳住节奏。"},quiz:{q:{th:"ในหนึ่งห้อง 4 จังหวะ จังหวะไหน “หนัก” ที่สุด?",en:"In a 4-beat bar, which beat is strongest?",zh:"4拍小节里哪一拍最强?"},choices:[{th:"จังหวะที่ 1",en:"Beat 1",zh:"第1拍"},{th:"จังหวะที่ 3",en:"Beat 3",zh:"第3拍"},{th:"ทุกจังหวะหนักเท่ากัน",en:"They are all equal",zh:"每拍一样强"}],correct:0}},{id:"tc-slow-first",tags:["ช้า","tempo","เร็ว","สะดุด","ติด","practice","ฝึก"],tier:0,source:"practice-wiki",diagram:null,concept:{th:"ซ้อมช้าก่อน = เร็วได้จริงภายหลัง",en:"Practice slow now to play fast later",zh:"先慢练，之后才能真正快起来"},why:{th:"สมองจด “ลำดับนิ้ว” ได้เมื่อไม่เร่ง — ซ้อมช้าจนลื่นแล้วค่อยเร่ง จะสะดุดน้อยลงวัดได้จากความแม่นยำ",en:"The brain only memorises the finger sequence when you stop rushing — slow until it's smooth, then speed up; the accuracy number proves it.",zh:"不赶的时候大脑才能记住指法顺序——先练顺再加速，准确率会证明这一点。"},quiz:{q:{th:"เจอท่อนที่ติด ๆ ขั้นแรกคืออะไร?",en:"First move on a passage that keeps breaking down?",zh:"段落总卡壳的第一步是什么?"},choices:[{th:"เร่งซ้อมซ้ำเร็ว ๆ จนผ่าน",en:"Repeat it fast until it sticks",zh:"快速反复硬冲"},{th:"ลดเทมโป ช้าลงแล้วค่อยเร่ง",en:"Slow the tempo down, speed up later",zh:"放慢速度，之后再加速"},{th:"ข้ามไปท่อนอื่นก่อน",en:"Skip to another section",zh:"先跳到别的段落"}],correct:1}},{id:"tc-finger-numbers",tags:["นิ้ว","fingering","finger","มือ","position"],tier:0,source:"piano-pedagogy-wiki",diagram:{type:"kb-scale",notes:["C","D","E","F","G"]},concept:{th:"นิ้วมีเลขประจำ: 1 = โป้ง … 5 = ก้อย",en:"Fingers are numbered: 1 = thumb … 5 = pinky",zh:"手指有编号：1=拇指 … 5=小指"},why:{th:"เลขนิ้วคือ GPS ของมือ — วางนิ้วตามเลขตั้งแต่ต้นท่อน แล้วท่อนที่เคยพลาดจะง่ายขึ้นเพราะมือไม่พันกัน",en:"Fingering is the hand's GPS — set the fingers by number at the start of the passage and the part you keep missing gets easier because the hand stops tangling.",zh:"指法就是手的GPS——开头就按编号放好手指，常错的段落会因为手不乱而变容易。"},quiz:{q:{th:"นิ้วโป้งมือขวาเรียกเลขอะไร?",en:"What is the number of the right-hand thumb?",zh:"右手的拇指是第几指?"},choices:[{th:"เลข 1",en:"1",zh:"第1指"},{th:"เลข 3",en:"3",zh:"第3指"},{th:"เลข 5",en:"5",zh:"第5指"}],correct:0}},{id:"tc-landmarks",tags:["อ่านโน้ต","โน้ต","sight","reading","note"],tier:0,source:"sight-reading-wiki",diagram:{type:"kb-scale",notes:["C","F","G"]},concept:{th:"โน้ตค้ำหมู่: จำ C · F · G แล้วอ่านตัวอื่นเทียบจากเพื่อนบ้าน",en:"Landmark notes: memorise C · F · G and read the rest relative to them",zh:"地标音：记住C·F·G，其他音相对着读"},why:{th:"อ่านโน้ตทีละตัวคือช้าที่สุด — จำจุดค้ำไม่กี่จุดแล้วมอง “ขึ้น/ลง/ข้าง” จากจุดค้ำ จะอ่านหน้าโน้ตเร็วขึ้นจริง",en:"Reading note-by-note is the slowest way — anchor a few landmarks and judge up/down/step from them; sight-reading genuinely speeds up.",zh:"一个音一个音读是最慢的——记住几个地标，看相对位置，识谱真的会变快。"},quiz:{q:{th:"ประโยชน์ของ “โน้ตค้ำหมู่” คืออะไร?",en:"What are landmark notes for?",zh:"地标音的作用是什么?"},choices:[{th:"ใช้เทียบตำแหน่งโน้ตอื่นได้เร็วขึ้น",en:"Read other notes faster relative to them",zh:"更快地读出其他音"},{th:"ทำให้เสียงดังขึ้น",en:"They make the sound louder",zh:"让声音更响"},{th:"ไม่ต้องอ่านโน้ตอื่นอีกเลย",en:"You never read other notes",zh:"从此不用读其他音"}],correct:0}},{id:"tc-half-steps",tags:["ครึ่งเสียง","เสียง","semitone","half","คีย์ดำ","black"],tier:0,source:"interval-wiki",diagram:{type:"half-steps",notes:["E","F"]},concept:{th:"ครึ่งเสียงคือระยะสั้นสุด — คู่ E–F และ B–C “ไม่มีคีย์ดำคั่น”",en:"A semitone is the smallest step — E–F and B–C have no black key between them",zh:"半音是最小距离——E–F和B–C之间没有黑键"},why:{th:"หลายท่อนพลาดเพราะกด “ข้างกัน” ผิด — จำสองคู่ไร้ดำคั่นนี้แล้วหาโน้ตและแก้ที่พลาดเร็วขึ้น",en:"Many misses are just pressing the wrong neighbour — remember these two no-black-key pairs and you find and fix wrong notes faster.",zh:"很多错音只是按错隔壁键——记住这两对没有黑键的组合，找音和改错都会更快。"},quiz:{q:{th:"คู่ไหน “ไม่มีคีย์ดำคั่นกลาง”?",en:"Which pair has no black key between them?",zh:"哪一对之间没有黑键?"},choices:[{th:"C–D",en:"C–D",zh:"C–D"},{th:"E–F",en:"E–F",zh:"E–F"},{th:"F–G",en:"F–G",zh:"F–G"}],correct:1}},{id:"tc-dynamics",tags:["ดัง","เบา","dynamic","dynamics","เสียง"],tier:1,source:"dynamics-wiki",diagram:{type:"dynamics",mark:3},concept:{th:"p → f คือช่วงเสียง — ดนตรีสนุกขึ้นเมื่อมีเบา-ดังสลับ",en:"p → f is a range — music gets lively when soft and loud alternate",zh:"p→f是力度范围——强弱交替音乐才生动"},why:{th:"เล่นดังเท่ากันทั้งท่อนคือเหตุผลที่ฟังแล้ว “แบน” — เลือกจุดเน้นสัก 2-3 จุดต่อท่อน ผู้ฟังจะตามเราได้",en:"One flat volume is why a piece sounds lifeless — pick 2-3 emphasis points per section and listeners follow you.",zh:"全曲一样响听起来会平——每段选2-3个强调点，听众就会跟着你走。"},quiz:{q:{th:"mf กับ p อันไหนดังกว่า?",en:"Which is louder, mf or p?",zh:"mf和p哪个更响?"},choices:[{th:"p",en:"p",zh:"p"},{th:"mf",en:"mf",zh:"mf"},{th:"เท่ากัน",en:"The same",zh:"一样"}],correct:1}},{id:"tc-hands-apart",tags:["สองมือ","มือ","hands","รวม"],tier:1,source:"piano-pedagogy-wiki",diagram:null,concept:{th:"ซ้อมมือแยกให้ลื่น ก่อนรวมสองมือ",en:"Smooth hands-separately first, then combine",zh:"先分手练顺，再双手合"},why:{th:"สองมือสะดุดเพราะ “คิวงาน” ของแต่ละมือยังไม่ชัด — ซ้อมแยกจนไม่ต้องคิด แล้วรวมแบบช้า ๆ จะติดเร็วกว่า",en:"Hands-together stumbles because each hand's job isn't automatic yet — drill each until effortless, then combine slowly; it locks in faster.",zh:"合手卡是因为每只手的任务还不熟练——分开练到不用想，再慢慢合，很快就能锁住。"},quiz:{q:{th:"ก่อนเล่นสองมือรวม ควรทำอะไร?",en:"What should you do before hands together?",zh:"双手合之前应该做什么?"},choices:[{th:"ซ้อมสองมือพร้อมกันซ้ำ ๆ เลย",en:"Repeat hands together right away",zh:"直接反复双手合练"},{th:"ซ้อมแยกมือจนลื่นก่อน",en:"Drill each hand until smooth first",zh:"先分手练到流畅"},{th:"ดูคลิปสาธิตแทนการซ้อม",en:"Watch a demo instead of practicing",zh:"看示范代替练习"}],correct:1}},{id:"tc-pedal-ear",tags:["เท้า","pedal","ครึม","ขุ่น"],tier:1,source:"sustain-pedal-wiki",diagram:null,concept:{th:"เท้าเปียโนคือ “หู” — เปลี่ยนเท้าตอนคอร์ดเปลี่ยน ไม่ใช่ตอนจังหวะมา",en:"The pedal is an ear — change it when the chord changes, not when the beat arrives",zh:"踏板是耳朵——和弦换了才换，不是每拍都换"},why:{th:"เสียงขุ่นมาจากการเหยียบค้างข้ามคอร์ด — ฟังจนเสียงเริ่ม “ขุ่น” แล้วยกเท้าพร้อมคอร์ดใหม่ เสียงจะใสทันที",en:"The muddy sound is the pedal held across chords — listen for the blur and lift with the new chord; it clears instantly.",zh:"浑浊的声音是踏板跨和弦踩住造成的——听到变糊就跟着新和弦抬换，声音立刻干净。"},quiz:{q:{th:"ควรยก-เปลี่ยนเปียโนเท้าเมื่อไร?",en:"When should you change the sustain pedal?",zh:"什么时候应该换踏板?"},choices:[{th:"ทุกจังหวะที่ 1 เสมอ",en:"Always on every beat 1",zh:"每拍第1下都换"},{th:"ตอนคอร์ดเปลี่ยน",en:"When the chord changes",zh:"和弦变化时"},{th:"จบเพลงค่อยยก",en:"Only at the end",zh:"曲终才抬"}],correct:1}},{id:"tc-chunking",tags:["จำ","memory","ลืม","ยาว","ท่อน"],tier:1,source:"chunking-wiki",diagram:null,concept:{th:"จำเป็น “ก้อน” — ซ้อมท่อนเล็ก 4-8 ตัวโน้ต แล้วค่อยต่อกัน",en:"Memorise in chunks — drill 4-8 note pieces, then chain them",zh:"分块记忆——先练4-8个音的小段，再连起来"},why:{th:"สมองจำทั้งเพลงพร้อมกันไม่ได้ แต่จำ “ก้อนเล็ก” ได้เก่ง — ซ้อมก้อนจนลื่น แล้วเชื่อมก้อนทีละคู่",en:"The brain can't hold a whole piece at once, but it's great at small chunks — drill each chunk smooth, then link them pair by pair.",zh:"大脑一次记不住整首曲子，但很擅长记小块——把每块练顺，再两两相连。"},quiz:{q:{th:"วิธีจำท่อนยาวที่ได้ผลที่สุดคือ?",en:"The most effective way to memorise a long passage?",zh:"记长段落最有效的方法是?"},choices:[{th:"เล่นทั้งท่อนซ้ำรวดเดียวยาว ๆ",en:"One long run-through after another",zh:"一遍遍整段拉长练"},{th:"แบ่งก้อนเล็ก ซ้อมจนลื่น แล้วต่อกัน",en:"Chunk it, drill smooth, then chain",zh:"分块练顺再连接"},{th:"เปิดโน้ตเล่นตามไปเรื่อย ๆ",en:"Keep reading along from the score",zh:"一直看着谱子跟弹"}],correct:1}},{id:"tc-spaced-review",tags:["ทบทวน","review","ลืม","remember"],tier:1,source:"spaced-repetition-wiki",diagram:null,concept:{th:"ทบทวน “ก่อนจะลืม” ได้ผลกว่าซ้อมรวดเดียวยาว",en:"Reviewing just before you forget beats one long session",zh:"快忘时复习胜过一次练很久"},why:{th:"งานวิจัยการเรียนรู้ยืนยันตรงกัน: สั้น ๆ หลายครั้งห่างกันเป็นวัน จำได้นานกว่า — แอปจัด “ครบกำหนดทบทวน” ให้แล้ว แค่กลับมาทำตาม",en:"Learning research agrees: short sessions spaced over days stick longer — the app already schedules due reviews, just come back and do them.",zh:"学习研究一致表明：短时多次、间隔几天记得更牢——应用已经排好复习计划，照着回来练就行。"},quiz:{q:{th:"การทบทวนแบบไหนจำได้นานกว่า?",en:"Which review schedule sticks longer?",zh:"哪种复习记得更久?"},choices:[{th:"สั้น ๆ หลายครั้ง เว้นเป็นวัน",en:"Short sessions spaced across days",zh:"短时多次、间隔几天"},{th:"ยาว ๆ ครั้งเดียวจบ",en:"One long marathon",zh:"一次长时间练完"},{th:"ทบทวนเฉพาะก่อนสอบ",en:"Only right before an exam",zh:"只在考试前复习"}],correct:0}},{id:"tc-metre-34",tags:["3/4","วอลตซ์","waltz","metre","จังหวะ"],tier:1,source:"metre-wiki",diagram:{type:"rhythm-grid",beats:[1,.5,.5]},concept:{th:"3/4 คือ “ปัง-ฉะ-ฉะ” — หนักที่ 1 เบาที่ 2-3",en:"3/4 is OOM-pah-pah — strong on 1, light on 2-3",zh:"3/4是“蹦-嚓-嚓”——1强，2-3弱"},why:{th:"ท่อน 3/4 พลาดมักเพราะมือยังนับอยู่ใน 4 — จำรูปท่าหนัก-เบา-เบา แล้วมือจะวนถูกห้องเอง",en:"3/4 misses usually come from still counting in 4 — lock in the strong-weak-weak shape and the hand circles the bar correctly by itself.",zh:"3/4弹错多半是还在按4拍数——记住强弱弱的形状，手会自己走对每小节。"},quiz:{q:{th:"จังหวะหนักของห้อง 3/4 อยู่ที่ไหน?",en:"Where is the strong beat in 3/4?",zh:"3/4的重拍在哪里?"},choices:[{th:"จังหวะที่ 1",en:"Beat 1",zh:"第1拍"},{th:"จังหวะที่ 2",en:"Beat 2",zh:"第2拍"},{th:"จังหวะที่ 3",en:"Beat 3",zh:"第3拍"}],correct:0}},{id:"tc-stage-calm",tags:["เวที","เสียงใจ","ประสาท","เครียด","stage","กลัว"],tier:2,source:"stage-fright-wiki",diagram:null,concept:{th:"ใจเต้นก่อนเล่นเป็นเรื่องปกติ — หายใจนับ 4 ช่วยมือคลายจริง",en:"Stage nerves are normal — 4-count breathing genuinely relaxes the hands",zh:"上台紧张很正常——数4拍呼吸真能让手放松"},why:{th:"ความกังวลทำแขน-มือตึงแล้วพลาดขึ้น — หายใจเข้า 4 นับ ออก 4 นับ สองรอบ ก่อนเริ่ม ลดความตึงได้จริง ไม่ใช่คำแนะนำลอย ๆ",en:"Anxiety tightens arms and hands, causing the misses — two rounds of 4-count in/out before starting measurably relaxes them; this isn't generic advice.",zh:"紧张会让手臂和手发紧导致错音——开始前做两轮4拍吸呼，可测地放松，不是空话。"},quiz:{q:{th:"ก่อนขึ้นเล่น วิธีไหนช่วยคลายมือตึง?",en:"What helps relax tense hands before playing?",zh:"上台前什么方法能放松手?"},choices:[{th:"กำมือแน่น ๆ ไว้",en:"Squeeze fists tightly",zh:"用力握拳"},{th:"หายใจช้า ๆ นับ 4 เข้า-ออก",en:"Slow 4-count breathing in and out",zh:"数4拍缓慢呼吸"},{th:"รีบเริ่มเล่นเร็ว ๆ จะได้ไม่คิดมาก",en:"Rush into playing to avoid thinking",zh:"赶紧开始弹免得多想"}],correct:1}}],p="tg_kstats";function l(){try{const e=JSON.parse(c().getItem(p)||"null");return e&&typeof e=="object"?{streak:0,bestStreak:0,lastDay:null,correct:0,answered:0,seen:{},...e}:{streak:0,bestStreak:0,lastDay:null,correct:0,answered:0,seen:{}}}catch{return{streak:0,bestStreak:0,lastDay:null,correct:0,answered:0,seen:{}}}}function y(e){try{c().setItem(p,JSON.stringify(e||{}))}catch{}}function D(e){const t=l(),n=o();if(t.lastDay!==n){const i=new Date(Date.now()-864e5);t.streak=t.lastDay===o(i)?(t.streak||0)+1:1,t.lastDay=n,t.bestStreak=Math.max(t.bestStreak||0,t.streak)}return t.answered=(t.answered||0)+1,e&&(t.correct=(t.correct||0)+1),y(t),t}function F(e){if(!e)return;const t=l();t.seen=t.seen||{},t.seen[e]=o(),y(t)}const f=864e5;function v(e,t){try{return Math.floor((t-new Date(e+"T00:00:00").getTime())/f)}catch{return 9999}}function T({level:e=0,struggleLabel:t=null,now:n=Date.now(),seenOverride:i=null}={}){const z=e<=2?0:e>=8?2:1,u=q.filter(a=>(a.tier||0)<=z),d=(t||"").toLowerCase(),g=d?u.filter(a=>(a.tags||[]).some(s=>d.includes(String(s).toLowerCase()))):[];let h=g.length?g:u;if(!h.length)return null;const w=l(),b=i||w.seen||{},m=h.filter(a=>{const s=v(b[a.id],n);return!(s>=0&&s<7)});m.length&&(h=m);const k=Math.floor(n/f)%h.length;return h[k]||h[0]}function E(){try{const e=JSON.parse(c().getItem("tg_note_miss")||"{}");return e&&typeof e=="object"?e:{}}catch{return{}}}function G(e){const t=e&&S[e.source];return t?{institution:t.institution,url:t.url}:{institution:null,url:null}}export{q as TEACH_CARDS,D as bumpKnowledgeStats,G as cardSourceInfo,F as markCardSeen,T as pickTeachCard,l as readKnowledgeStats,E as readNoteMissMap,y as writeKnowledgeStats};
